using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        // Server-side: caller must filter by user email before calling this.
        // This returns all; the API endpoint handles user filtering.
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<List<ShipmentDto>> GetShipmentsByEmailAsync(string email)
    {
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => s.ToDto())
            .ToListAsync();
    }

    public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment?.ToDto();
    }

    public async Task<bool> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return false;

        shipment.Status = newStatus;
        if (newStatus == ShipmentStatus.Delivered)
            shipment.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return true;
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (ServerShipmentService svc) =>
        {
            var shipments = await svc.GetAllShipmentsAsync();
            return Results.Ok(shipments);
        });

        group.MapGet("/mine", async (ClaimsPrincipal user, ServerShipmentService svc) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
            if (string.IsNullOrEmpty(email))
                return Results.Forbid();

            var shipments = await svc.GetShipmentsByEmailAsync(email);
            return Results.Ok(shipments);
        });

        group.MapGet("/track/{trackingNumber}", [AllowAnonymous] async (string trackingNumber, ServerShipmentService svc) =>
        {
            var shipment = await svc.TrackShipmentAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapPut("/{id:int}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusDto dto, ServerShipmentService svc) =>
        {
            var result = await svc.UpdateStatusAsync(id, dto.NewStatus);
            return result ? Results.Ok() : Results.NotFound();
        });
    }
}

