            <div class="row">
                <div class="col-md-6">
                    <h6 class="text-muted">Route</h6>
                    <p class="fs-5">@result.Origin → @result.Destination</p>

                    <h6 class="text-muted">Description</h6>
                    <p>@result.Description</p>
                </div>
                <div class="col-md-6">
                    <h6 class="text-muted">Shipped Date</h6>
                    <p>@result.ShippedDate.ToString("MMMM dd, yyyy")</p>

                    @if (result.ActualDelivery.HasValue)
                    {
                        <h6 class="text-muted">Delivered</h6>
                        <p class="text-success fw-bold">@result.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                    else if (result.EstimatedDelivery.HasValue)
                    {
                        <h6 class="text-muted">Estimated Delivery</h6>
                        <p class="fw-bold">@result.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>
            </div>

            @if (result.Status != ShipmentStatus.Delivered && result.Status != ShipmentStatus.Cancelled)
            {
                <div class="mt-3">
                    <h6 class="text-muted">Shipment Progress</h6>
                    <div class="progress" style="height: 25px;">
                        <div class="progress-bar @GetProgressBarClass(result.Status)"
                             role="progressbar"
                             style="width: @GetProgressPercent(result.Status)%"
                             aria-valuenow="@GetProgressPercent(result.Status)"
                             aria-valuemin="0" aria-valuemax="100">
                            @result.Status
                        </div>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? result;
    private bool searching;
    private bool searched;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searched = false;
        result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        searchedNumber = trackingNumber.Trim();
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Cancelled => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.OutForDelivery => "bg-warning",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delayed => 50,
        _ => 0
    };
}

